{"query": "
SELECT table_schema, table_name 
FROM information_schema.tables 
WHERE table_schema NOT IN ('pg_catalog', 'information_schema', 'auth', 'storage', 'realtime', 'extensions', 'pgbouncer', 'vault', 'pgsodium', 'graphql_public', 'graphql', 'net', 'cron')
ORDER BY table_schema, table_name;
"}

{"query": "
SELECT table_schema, table_name 
FROM information_schema.tables 
WHERE table_schema = 'employees'
ORDER BY table_name;
"}

{"query": "
SELECT table_name, column_name, data_type, is_nullable
FROM information_schema.columns
WHERE table_schema = 'employees'
ORDER BY table_name, ordinal_position;
"}

{"query": "
-- Check unique employee counts in department_employee
SELECT COUNT(DISTINCT employee_id) as unique_employees,
       COUNT(*) as total_records
FROM employees.department_employee;
"}

{"query": "
-- Drop if already exists, then recreate
DROP TABLE IF EXISTS employees.employee_retention_analysis;

CREATE TABLE employees.employee_retention_analysis (
    department_name   VARCHAR(100) NOT NULL,
    total_employees_ever INTEGER     NOT NULL,
    current_employees    INTEGER     NOT NULL,
    former_employees     INTEGER     NOT NULL,
    retention_rate       DECIMAL(8, 4) NOT NULL
);
"}

{"query": "
DROP TABLE IF EXISTS employees.high_risk_employees;

CREATE TABLE employees.high_risk_employees (
    employee_id        BIGINT       NOT NULL,
    full_name          VARCHAR(200) NOT NULL,
    current_department VARCHAR(100) NOT NULL,
    tenure_days        INTEGER      NOT NULL,
    current_salary     INTEGER      NOT NULL,
    risk_category      VARCHAR(20)  NOT NULL
);
"}

{"query": "
-- Sample of high-risk employees
SELECT * FROM employees.high_risk_employees 
WHERE risk_category = 'high_risk' 
LIMIT 5;
"}

{"query": "
DROP TABLE IF EXISTS employees.turnover_trend_analysis;

CREATE TABLE employees.turnover_trend_analysis (
    departure_year   INTEGER       NOT NULL,
    departures_count INTEGER       NOT NULL,
    avg_tenure_days  DECIMAL(10, 4) NOT NULL,
    avg_final_salary DECIMAL(12, 4) NOT NULL
);
"}

{"query": "
-- Cross-check: total current employees in high_risk table vs source
SELECT 
    (SELECT COUNT(*) FROM employees.high_risk_employees)                              AS hre_total,
    (SELECT COUNT(DISTINCT employee_id) FROM employees.salary WHERE to_date = '9999-01-01') AS salary_current;
"}
